        "title": "তৃতীয় অধ্যায়: চরম নাটকীয় মোড় ও মুখোশ উন্মোচন",
        "content": [
          "রাত যখন তৃতীয় প্রহরে গড়াল, তখন হঠাৎ বাইরের বৃষ্টি থেমে গেল। এক অদ্ভুত নিস্তব্ধতা নেমে এলো চারধারে। সেই নিস্তব্ধতা ছিল ঝড়ের চেয়েও বেশি ভীতিপ্রদ। দূরে কোথাও এক নিশাচর পাখি ডেকে উঠেই থেমে গেল।",
          "হঠাৎ চিলেকোঠার দিক থেকে একটি মৃদু কিন্তু স্পষ্ট খসখস শব্দ শোনা গেল। জাহিদ নিঃশব্দে হাত বাড়িয়ে একটি ভারী পিতলের বাতিদান তুলে নিল। সে ইশারায় বাকি দুজনকে পেছনের দিকে সরে যেতে বলল। ধীর পায়ে সে সিঁড়ির দিকে এগোতে লাগল। প্রতিটি কাঠের ধাপ অতিক্রম করার সময় বুকের ভেতরের হৃৎস্পন্দন কানে এসে বাজছিল।",
          "দরজাটি সন্তর্পণে একটু ফাঁক করতেই ঘরের ভেতরে এক অচেনা অবয়ব নজরে এলো। আলো পড়তেই সেই ব্যক্তির মুখ স্পষ্টভাবে উন্মোচিত হলো। জাহিদ বিস্ময়ে হতবাক হয়ে দু পা পিছিয়ে গেল। \"তুমি? তুমি বেঁচে আছো? কিন্তু কীভাবে সম্ভব?\"",
          "সেই মুখটি এক অদ্ভুত নিষ্ঠুর হাসিতে উদ্ভাসিত হয়ে উঠল। সে ধীরপায়ে এগিয়ে এসে বলল, \"মানুষ যাকে মৃত্যু মনে করে, তা কখনো কখনো কেবল দীর্ঘ এক প্রস্তুতি মাত্র। তোমাদের সুখের প্রাসাদ গুঁড়িয়ে দেওয়ার জন্যই আমি মৃত্যুর ওপার থেকে ফিরে এসেছি।\"",
          "তখনই পেছন থেকে বিষাক্ত এবং শফিক সাহেব ছুটে এলো। এই আকস্মিক মুখোমুখি সাক্ষাতে পুরো অতীত এক নিমেষে তাদের চোখের সামনে ভেসে উঠল। যে মানুষটিকে এতদিন সবাই বন্ধু অথবা শুভাকাঙ্ক্ষী মনে করেছিল, আসলে সেই ছিল সমস্ত চক্রান্ত ও ধ্বংসের মূল পরিকল্পনাকারী!",
          "মুখোশ খসে পড়তেই সত্যের আলো তাদের ওপর তীব্র এক আলোর মতো ঝরে পড়ল। ভুল বোঝাবুঝির কালো মেঘ কেটে গেল, আর জেগে উঠল সত্যের এক অপ্রতিরোধ্য তেজ। সেই সংকীর্ণ ঘরের ভেতরে শুরু হলো জীবনের এক চরম লড়াই, যা নির্ধারিত করবে কার জয় আর কার চিরতরে পতন হবে।"
        ]
