          "মিথ্যার দেওয়াল ভেঙে চুরমার হয়ে গেছে। যে অন্ধকার তাদের এতদিন অবরুদ্ধ করে রেখেছিল, সত্যের জ্বলন্ত আগুনে তা নিঃশেষে ভস্মীভূত হয়ে গেছে। ক্ষতবিক্ষত হলেও মোর্শেদ এবং শেষ একে অপরের হাত শক্ত করে ধরে ভোরের আলোয় বাইরে এসে দাঁড়াল।",
          "শফিক সাহেব নদীর ঘাটের দিকে তাকিয়ে বলল, \"রাত কেটে গেছে। যে নদীর জলে রাতের সমস্ত কান্না ধুয়ে গেছে, সেই নদীর জলই আবার নতুন দিনে জীবন দেবে। আমরা বেঁচে রইলাম, কারণ আমাদের বিশ্বাস ছিল খাঁটি।\"",
          "শেষ মৃদু হেসে আকাশের দিকে তাকাল। সেখানে একঝাঁক সাদা পায়রা ডানা মেলে উড়ে যাচ্ছিল মুক্ত বাতাসে। সে বলল, \"কষ্ট মানুষকে ভেঙে ফেলে না মোর্শেদ, বরং খাঁটি সোনার মতো পুড়িয়ে উজ্জ্বল করে তোলে। আজ আমাদের আর কোনো ভয় নেই।\"",
          "মোর্শেদ তার চোখে চোখ রেখে বলল, \"হ্যাঁ, যে পথ আমরা অতিক্রম করেছি, তা হয়তো বড় কঠিন ছিল। কিন্তু এই চলার পথেই আমরা মানুষকে চিনতে পেরেছি, ভালোবাসার আসল রূপকে উপলব্ধি করতে পেরেছি। এই অনুভূতি আমাদের আজীবন আলো দেখাবে।\"",
          "সূর্য তখন পুরোপুরি উঠে পড়েছে। সুবর্ণ কিরণে ধুয়ে যাচ্ছে মেঠোপথ, বৃক্ষরাজি আর দূর দিগন্তের শান্ত নদী। এক মহান আত্মোপলব্ধি আর পরম শান্তির স্পর্শ নিয়ে শেষ হলো এই দীর্ঘ উপাখ্যান, যা পাঠকের অন্তরে চিরকাল এক অবিস্মরণীয় অনুপ্রেরণার সুর হয়ে বেঁচে থাকবে।"
